'use strict';
/* ============================================================================
   lesson-match-data.js — what each lesson is ABOUT, for matching exam questions to it
   (Patryk 2026-10-15: off-topic Do Nows, board questions and exam practice).

   Hand-written from every lesson in the schemes (planner-data.json, 417 lessons) against every
   subtopic in the exam library (100 AQA GCSE, 68 OCR A-level). Keyed by the planner's topic name
   (= the Drive macrotopic folder). Each topic:
     subs : the exam library subtopics its lessons draw on (AQA subtopic / OCR sub-subtopic names)
     L    : lesson title -> "key words | need: words | subs: A; B | min: n"
            key words : what a question must be about (any one, unless min says more). A word
                        matches any word starting with it ("magnif" -> magnification); a word under
                        4 letters must match whole ("ion", "ldr"); words with a space are phrases.
            need      : at least one of THESE must be there (the words that make it this lesson)
            subs      : this lesson's own subtopics (instead of the topic's)
            "none"    : no exam questions for this lesson (safety talks, ICT tasks, assessments)
   Revision / review / summary lessons use every lesson of their topic. Assessment and DIRT
   lessons use none. A lesson not listed falls back to its own title words within the topic.
   ============================================================================ */

